package io.github.rebrowser.data;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.crypto.*;
import java.io.IOException;
import java.lang.reflect.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.security.GeneralSecurityException;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import org.junit.Test;
/** Real bounded HOST filesystem/JCA pipeline via PRIVATE toy wrapping-key/path fixtures, NOT Android. */
public final class PrivateRecordStoreTest {
 private static final class F implements AutoCloseable {
  final Path root;final AtomicReference<ComponentGate.SourceView> source=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,source::get);final ComponentGate.BusinessPermit permit=gate.requireBusiness();final DataKeyVault vault;final PrivateRecordStore store;
  F()throws Exception{root=Files.createTempDirectory("private-records-host-");Constructor<DataKeyVault> v=DataKeyVault.class.getDeclaredConstructor(SecretKey.class,ComponentGate.class,byte[].class,boolean.class);assertTrue(Modifier.isPrivate(v.getModifiers()));v.setAccessible(true);vault=v.newInstance(new SecretKeySpec(new byte[32],"AES"),gate,new byte[16],false);store=create(root,gate,vault);}
  PrivateRecordStore.Reference ref(){return store.reference(PrivateRecordSealer.Purpose.BROWSER_CATALOG,new byte[16],permit);}
  PrivateRecordStore.ReadStamp missing(PrivateRecordStore.Reference ref)throws Exception{try(PrivateRecordStore.ReadRecord read=store.read(ref,permit)){assertEquals(PrivateRecordStore.Kind.MISSING,read.stamp().kind());return read.stamp();}}
  @Override public void close()throws Exception{try(java.util.stream.Stream<Path> files=Files.walk(root)){for(Path p:files.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.delete(p);}}
 }
 private static PrivateRecordStore create(Path root,ComponentGate gate,DataKeyVault vault)throws Exception{Constructor<PrivateRecordStore> c=PrivateRecordStore.class.getDeclaredConstructor(Path[].class,ComponentGate.class,byte[].class,DataKeyVault.class,boolean.class);assertTrue(Modifier.isPrivate(c.getModifiers()));c.setAccessible(true);try{return c.newInstance(new Path[]{root},gate,new byte[16],vault,false);}catch(InvocationTargetException e){throw (Exception)e.getCause();}}
 @Test public void absentRecordDoesNotSeedDirectoryOrKeyOrFakePlaintext()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();try(PrivateRecordStore.ReadRecord read=f.store.read(ref,f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,read.stamp().kind());assertEquals(0,read.stamp().revision());assertThrows(IllegalStateException.class,read::plaintextCopy);}assertFalse(Files.exists(f.root.resolve(ref.opaqueRef())));assertFalse(f.store.hasOwnedIoInFlight());}}
 @Test public void nativeOwnedCiphertextCasWriteReadReopenPipeline()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp one=f.store.write(f.missing(ref),new byte[]{1,2,3},f.permit);assertEquals(1,one.revision());assertTrue(Files.size(f.root.resolve(ref.opaqueRef()))==163);assertFalse(Arrays.equals(new byte[]{1,2,3},Files.readAllBytes(f.root.resolve(ref.opaqueRef()))));try(PrivateRecordStore.ReadRecord read=f.store.read(ref,f.permit)){assertArrayEquals(new byte[]{1,2,3},read.plaintextCopy());}PrivateRecordStore reopened=create(f.root,f.gate,f.vault);try(PrivateRecordStore.ReadRecord read=reopened.read(reopened.reference(ref.purpose(),new byte[16],f.permit),f.permit)){assertArrayEquals(new byte[]{1,2,3},read.plaintextCopy());}PrivateRecordStore.ReadStamp two=f.store.write(one,new byte[]{4},f.permit);assertEquals(2,two.revision());}}
 @Test public void staleMissingAndStaleContentStampCannotOverwriteNewerRecord()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp zero=f.missing(ref),one=f.store.write(zero,new byte[]{1},f.permit);assertThrows(IOException.class,()->f.store.write(zero,new byte[]{2},f.permit));f.store.write(one,new byte[]{3},f.permit);assertThrows(IOException.class,()->f.store.write(one,new byte[]{4},f.permit));assertFalse(f.store.hasOwnedIoInFlight());}}
 @Test public void foreignStoreReferenceAndStampCannotBecomeLocalAuthority()throws Exception{try(F a=new F();F b=new F()){PrivateRecordStore.Reference other=b.ref();assertThrows(IllegalArgumentException.class,()->a.store.read(other,a.permit));PrivateRecordStore.ReadStamp stamp=b.missing(other);assertThrows(IllegalArgumentException.class,()->a.store.write(stamp,new byte[0],a.permit));}}
 @Test public void unfinishedStageIsUnknownAndNeverAutoDeletedOrRepaired()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp one=f.store.write(f.missing(ref),new byte[]{1},f.permit);Path stage=f.root.resolve(ref.opaqueRef()+".pending");Files.write(stage,new byte[]{9});try(PrivateRecordStore.ReadRecord read=f.store.read(ref,f.permit)){assertEquals(PrivateRecordStore.Kind.UNFINISHED_WRITE,read.stamp().kind());assertThrows(IllegalStateException.class,read::plaintextCopy);assertThrows(IllegalArgumentException.class,()->f.store.write(read.stamp(),new byte[]{2},f.permit));}assertThrows(IOException.class,()->f.store.write(one,new byte[]{2},f.permit));assertArrayEquals(new byte[]{9},Files.readAllBytes(stage));}}
 @Test public void corruptedRecordCannotReturnPrivatePlaintextOrBeAutoReplaced()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.store.write(f.missing(ref),new byte[]{1},f.permit);Path path=f.root.resolve(ref.opaqueRef());byte[] bytes=Files.readAllBytes(path);bytes[bytes.length-1]^=1;Files.write(path,bytes);assertThrows(GeneralSecurityException.class,()->f.store.read(ref,f.permit));assertArrayEquals(bytes,Files.readAllBytes(path));}}
 @Test public void wrongPurposeCannotReuseExistingNativeScopeCiphertext()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.store.write(f.missing(ref),new byte[]{1},f.permit);PrivateRecordStore.Reference other=f.store.reference(PrivateRecordSealer.Purpose.GECKO_CHECKPOINT,new byte[16],f.permit);Files.copy(f.root.resolve(ref.opaqueRef()),f.root.resolve(other.opaqueRef()));assertThrows(GeneralSecurityException.class,()->f.store.read(other,f.permit));}}
 @Test public void symlinkFileAndReplacedLockFailClosed()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();Path file=f.root.resolve(ref.opaqueRef()),target=f.root.resolve("unowned");Files.write(target,new byte[160]);Files.createSymbolicLink(file,target);assertThrows(IOException.class,()->f.store.read(ref,f.permit));Files.delete(file);f.missing(ref);Files.delete(f.root.resolve(".private-records.lock"));Files.createSymbolicLink(f.root.resolve(".private-records.lock"),target);assertThrows(IOException.class,()->f.store.read(ref,f.permit));}}
 @Test public void realHostLockBusyNeverWaitsOrWrites()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp zero=f.missing(ref);try(FileChannel c=FileChannel.open(f.root.resolve(".private-records.lock"),StandardOpenOption.WRITE);FileLock lock=c.lock()){assertThrows(IOException.class,()->f.store.write(zero,new byte[]{1},f.permit));}assertFalse(Files.exists(f.root.resolve(ref.opaqueRef())));assertFalse(f.store.hasOwnedIoInFlight());}}
 @Test public void epochOrSourceCutoverCannotRetargetExistingStore()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.missing(ref);f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));ComponentGate.BusinessPermit fresh=f.gate.requireBusiness();assertThrows(SecurityException.class,()->f.store.read(ref,fresh));assertThrows(SecurityException.class,()->f.store.reference(ref.purpose(),new byte[16],fresh));}}
 @Test public void retainedPrivatePlaintextCreditIsNotFreedByIoReturn()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.store.write(f.missing(ref),new byte[]{1},f.permit);PrivateRecordStore.ReadRecord held=f.store.read(ref,f.permit);assertFalse(f.store.hasOwnedIoInFlight());assertThrows(IllegalStateException.class,()->f.store.read(ref,f.permit));held.close();try(PrivateRecordStore.ReadRecord next=f.store.read(ref,f.permit)){assertArrayEquals(new byte[]{1},next.plaintextCopy());}}}
 @Test public void plaintextCopiesHaveExplicitOwnedLifetime()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.store.write(f.missing(ref),new byte[]{1,2},f.permit);PrivateRecordStore.ReadRecord read=f.store.read(ref,f.permit);byte[] external=read.plaintextCopy();external[0]=9;assertArrayEquals(new byte[]{1,2},read.plaintextCopy());read.close();read.close();assertThrows(IllegalStateException.class,read::plaintextCopy);assertEquals(9,external[0]);}}
 @Test public void referenceInputIsDefensiveAndCannotContainRawPaths()throws Exception{try(F f=new F()){byte[] scope=new byte[16];PrivateRecordStore.Reference ref=f.store.reference(PrivateRecordSealer.Purpose.BROWSER_CATALOG,scope,f.permit);scope[0]=1;assertTrue(ref.opaqueRef().matches("p1_[0-9a-f]{32}\\.v1"));assertTrue(ref.opaqueRef().contains("00000000000000000000000000000000"));assertThrows(IllegalArgumentException.class,()->f.store.reference(ref.purpose(),new byte[15],f.permit));}}
 @Test public void oversizedAndTinyFilesRejectBeforeReadingOrDecrypting()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();Path file=f.root.resolve(ref.opaqueRef());Files.write(file,new byte[1]);assertThrows(IOException.class,()->f.store.read(ref,f.permit));try(FileChannel c=FileChannel.open(file,StandardOpenOption.WRITE)){c.position(4*1024*1024+DataKeyVault.ENVELOPE_OVERHEAD);c.write(java.nio.ByteBuffer.wrap(new byte[]{1}));}assertThrows(IOException.class,()->f.store.read(ref,f.permit));}}
 @Test public void ownedSourceLockDoesNotEraseRecordOrPendingState()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.store.write(f.missing(ref),new byte[]{1},f.permit);byte[] saved=Files.readAllBytes(f.root.resolve(ref.opaqueRef()));f.source.set(ComponentGate.SourceView.untrusted(ComponentGate.SourceState.LOCKED));assertThrows(SecurityException.class,()->f.store.read(ref,f.permit));assertArrayEquals(saved,Files.readAllBytes(f.root.resolve(ref.opaqueRef())));}}
 @Test public void unknownDirectoryObjectsBlockNewWritesButAreNeverDeleted()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp zero=f.missing(ref);Path unrelated=f.root.resolve("unknown-object");Files.write(unrelated,new byte[]{1});assertThrows(IOException.class,()->f.store.write(zero,new byte[0],f.permit));assertArrayEquals(new byte[]{1},Files.readAllBytes(unrelated));assertFalse(Files.exists(f.root.resolve(ref.opaqueRef()+".pending")));}}
 @Test public void boundedDiskAdmissionIncludesExistingRecordsAndNewStage()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();PrivateRecordStore.ReadStamp zero=f.missing(ref);Path other=f.root.resolve("p2_11111111111111111111111111111111.v1");try(FileChannel c=FileChannel.open(other,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){c.position(PrivateRecordStore.MAX_OWNED_DISK_BYTES-1);c.write(java.nio.ByteBuffer.wrap(new byte[]{0}));}assertThrows(IOException.class,()->f.store.write(zero,new byte[0],f.permit));assertFalse(Files.exists(f.root.resolve(ref.opaqueRef())));}}
 @Test public void nativeReferenceMetadataCannotGrowWithoutLimit()throws Exception{try(F f=new F()){for(int i=0;i<PrivateRecordStore.MAX_RECORDS;i++){byte[] scope=new byte[16];java.nio.ByteBuffer.wrap(scope).putInt(i);f.store.reference(PrivateRecordSealer.Purpose.GECKO_CHECKPOINT,scope,f.permit);}byte[] next=new byte[16];next[15]=1;assertThrows(IllegalStateException.class,()->f.store.reference(PrivateRecordSealer.Purpose.BROWSER_CATALOG,next,f.permit));}}
 @Test public void nonemptyLockIsNotSilentlyTrustedOrTruncated()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref();f.missing(ref);Path lock=f.root.resolve(".private-records.lock");Files.write(lock,new byte[]{1});assertThrows(IOException.class,()->f.store.read(ref,f.permit));assertArrayEquals(new byte[]{1},Files.readAllBytes(lock));}}
 @Test public void noPublicPathProviderAndMissingNativeFactoryDoesNotCreateDirectory()throws Exception{assertEquals(0,PrivateRecordStore.class.getConstructors().length);try(F f=new F()){assertThrows(IllegalArgumentException.class,()->PrivateRecordStore.openExisting(null,f.gate,new byte[16],f.permit));}}
}
